package org.kylepitcock.legacyconnector.core.synth;

import java.lang.invoke.MethodHandle;
import java.lang.invoke.MethodHandles;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.Collections;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.WeakHashMap;
import java.util.concurrent.ConcurrentHashMap;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Runtime support for the synthesized legacy API (classes generated by the loader's {@code SynthJarBuilder} for
 * legacy APIs the hand-written shim does not implement). Generated bytecode calls into this class only.
 */
public final class Synth {
    private static final Logger LOG = LoggerFactory.getLogger("LegacyConnector/Stubs");
    /** Returned by {@link #dispatch} when the receiver does not override the missing method. */
    public static final Object NONE = new Object();

    private static final Set<String> REPORTED = ConcurrentHashMap.newKeySet();
    private static final Map<Class<?>, Map<String, Optional<MethodHandle>>> DISPATCH = new ConcurrentHashMap<>();
    /** Side storage for fields missing from hand-written shim classes; identity-keyed, weak. */
    private static final Map<Object, Map<String, Object>> FIELDS = Collections.synchronizedMap(new WeakHashMap<>());
    private static final Map<String, Object> STATIC_FIELDS = new ConcurrentHashMap<>();

    private Synth() {}

    /** A synthesized method ran: logs the first call of each, so the log lists the stubs a modpack really uses. */
    public static void stub(String api) {
        if (REPORTED.add(api)) {
            LOG.info("Legacy API {} is not implemented yet; using a default ({} distinct so far)", api, REPORTED.size());
        }
    }

    public static Set<String> reported() {
        return Set.copyOf(REPORTED);
    }

    /**
     * Calls {@code name desc} on {@code receiver} if its class (a mod class extending a shim class) declares it,
     * as legacy virtual dispatch would have. Returns {@link #NONE} otherwise.
     */
    public static Object dispatch(Object receiver, String name, String desc, Object[] args) throws Throwable {
        if (receiver == null) return NONE;
        Optional<MethodHandle> handle = DISPATCH.computeIfAbsent(receiver.getClass(), k -> new ConcurrentHashMap<>())
                .computeIfAbsent(name + desc, k -> find(receiver.getClass(), name, desc));
        if (handle.isEmpty()) return NONE;
        Object[] all = new Object[args.length + 1];
        all[0] = receiver;
        System.arraycopy(args, 0, all, 1, args.length);
        return handle.get().invokeWithArguments(all);
    }

    private static Optional<MethodHandle> find(Class<?> type, String name, String desc) {
        for (Class<?> c = type; c != null && c != Object.class; c = c.getSuperclass()) {
            String pkg = c.getPackageName();
            if (pkg.startsWith("legacyconnector.") || pkg.startsWith("org.kylepitcock.legacyconnector")) continue; // shim/runtime
            for (Method m : c.getDeclaredMethods()) {
                if (!m.getName().equals(name) || Modifier.isStatic(m.getModifiers()) || !descriptor(m).equals(desc)) continue;
                try {
                    m.setAccessible(true);
                    return Optional.of(MethodHandles.lookup().unreflect(m));
                } catch (ReflectiveOperationException | RuntimeException e) {
                    LOG.debug("Cannot dispatch {}{} to {}", name, desc, c.getName(), e);
                    return Optional.empty();
                }
            }
        }
        return Optional.empty();
    }

    static String descriptor(Method m) {
        StringBuilder sb = new StringBuilder("(");
        for (Class<?> p : m.getParameterTypes()) sb.append(p.descriptorString());
        return sb.append(')').append(m.getReturnType().descriptorString()).toString();
    }

    /** Side-stored field value; stores and returns {@code initial} on first access. */
    /** An inert instance of a synthesized class (no constructor runs, every field is its default), or null for abstract types. */
    public static Object blank(String className) {
        try {
            ClassLoader loader = Thread.currentThread().getContextClassLoader();
            Class<?> c = Class.forName(className, false, loader != null ? loader : Synth.class.getClassLoader());
            if (c.isInterface() || java.lang.reflect.Modifier.isAbstract(c.getModifiers())) return null;
            java.lang.reflect.Field f = sun.misc.Unsafe.class.getDeclaredField("theUnsafe");
            f.setAccessible(true);
            Object o = ((sun.misc.Unsafe) f.get(null)).allocateInstance(c);
            if (o instanceof legacyconnector.v1_12_2.net.minecraftforge.registries.IForgeRegistryEntry.Impl<?> impl) impl.mcc$initDelegate();
            return o;
        } catch (ReflectiveOperationException | RuntimeException | LinkageError e) {
            return null;
        }
    }

    /** Supplies the value of a static field the shim lacks (vanilla constants typed with classes only the synthesizer knows). */
    public interface StaticResolver {
        Object resolve(String key, Class<?> accessorClass);
    }

    private static final java.util.List<StaticResolver> RESOLVERS = new java.util.concurrent.CopyOnWriteArrayList<>();
    private static final java.util.Set<String> RESOLVED = ConcurrentHashMap.newKeySet();

    public static void addStaticResolver(StaticResolver resolver) {
        RESOLVERS.add(resolver);
    }

    public static Object getField(Object owner, String key, Object initial) {
        if (owner == null) {
            if (initial == null) {
                Object v = STATIC_FIELDS.get(key);
                if (v == null && !RESOLVERS.isEmpty() && RESOLVED.add(key)) {
                    Class<?> accessor = StackWalker.getInstance(StackWalker.Option.RETAIN_CLASS_REFERENCE).getCallerClass();
                    for (StaticResolver r : RESOLVERS) {
                        try {
                            v = r.resolve(key, accessor);
                        } catch (RuntimeException | LinkageError e) {
                            LOG.warn("Cannot resolve the static field {}: {}", key, e.toString());
                        }
                        if (v != null) {
                            STATIC_FIELDS.put(key, v);
                            break;
                        }
                    }
                }
                return v;
            }
            return STATIC_FIELDS.computeIfAbsent(key, k -> initial);
        }
        synchronized (FIELDS) {
            Map<String, Object> m = FIELDS.computeIfAbsent(owner, k -> new ConcurrentHashMap<>());
            Object v = m.get(key);
            if (v == null && initial != null) {
                m.put(key, initial);
                v = initial;
            }
            return v;
        }
    }

    public static void setField(Object owner, String key, Object value) {
        if (owner == null) {
            if (value == null) STATIC_FIELDS.remove(key);
            else STATIC_FIELDS.put(key, value);
            return;
        }
        synchronized (FIELDS) {
            Map<String, Object> m = FIELDS.computeIfAbsent(owner, k -> new ConcurrentHashMap<>());
            if (value == null) m.remove(key);
            else m.put(key, value);
        }
    }

    // Lenient unboxing for dispatch results and side-stored fields.

    public static int toInt(Object o) {
        return o instanceof Number n ? n.intValue() : o instanceof Character c ? c : o instanceof Boolean b ? (b ? 1 : 0) : 0;
    }

    public static long toLong(Object o) {
        return o instanceof Number n ? n.longValue() : toInt(o);
    }

    public static float toFloat(Object o) {
        return o instanceof Number n ? n.floatValue() : toInt(o);
    }

    public static double toDouble(Object o) {
        return o instanceof Number n ? n.doubleValue() : toInt(o);
    }

    public static boolean toBoolean(Object o) {
        return o instanceof Boolean b ? b : toInt(o) != 0;
    }

    public static byte toByte(Object o) {
        return (byte) toInt(o);
    }

    public static short toShort(Object o) {
        return (short) toInt(o);
    }

    public static char toChar(Object o) {
        return (char) toInt(o);
    }

    /** Implements a static method of a synthesized class ({@code args} boxed); see {@link #callStatic}. */
    public interface StaticMethod {
        Object call(Object[] args) throws Throwable;
    }

    private static final Map<String, StaticMethod> STATIC_METHODS = new ConcurrentHashMap<>();

    /** {@code key} is the legacy class and method name, e.g. {@code net.minecraft.potion.PotionType.getPotionTypeForName}. */
    public static void addStaticMethod(String key, StaticMethod method) {
        STATIC_METHODS.put(key, method);
    }

    /** Called first by every synthesized static method: the registered implementation's result, or {@link #NONE}. */
    public static Object callStatic(String key, Object[] args) throws Throwable {
        StaticMethod m = STATIC_METHODS.get(key);
        return m == null ? NONE : m.call(args);
    }
}
